DROP TABLE IF EXISTS `approval_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `approval_requests` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_id` bigint NOT NULL,
  `approval_type` varchar(30) NOT NULL DEFAULT 'MANAGER_EXCEPTION' COMMENT 'MANAGER_EXCEPTION | REP_CONFIRMATION',
  `violations` json NOT NULL DEFAULT (_utf8mb4'[]') COMMENT '[{type:''OVER_CREDIT_LIMIT'', exceeded_by:..},{type:''BELOW_FLOOR_PRICE'', line_no:..}]',
  `status` varchar(30) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING | APPROVED | REJECTED | RETURNED',
  `requested_by` bigint NOT NULL,
  `requested_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `decided_by` bigint DEFAULT NULL,
  `decided_at` datetime DEFAULT NULL,
  `decision_comment` text,
  PRIMARY KEY (`id`),
  KEY `fk_approval_requests_requested_by` (`requested_by`),
  KEY `fk_approval_requests_decided_by` (`decided_by`),
  KEY `ix_approval_pending` (`status`,`requested_at`),
  KEY `ix_approval_requests_order_id` (`order_id`),
  CONSTRAINT `fk_approval_requests_decided_by` FOREIGN KEY (`decided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_approval_requests_order_id` FOREIGN KEY (`order_id`) REFERENCES `sales_orders` (`id`),
  CONSTRAINT `fk_approval_requests_requested_by` FOREIGN KEY (`requested_by`) REFERENCES `users` (`id`),
  CONSTRAINT `approval_requests_chk_1` CHECK ((`approval_type` in (_utf8mb4'MANAGER_EXCEPTION',_utf8mb4'REP_CONFIRMATION'))),
  CONSTRAINT `approval_requests_chk_2` CHECK ((`status` in (_utf8mb4'PENDING',_utf8mb4'APPROVED',_utf8mb4'REJECTED',_utf8mb4'RETURNED'))),
  CONSTRAINT `ck_approval_requests_1` CHECK (((`status` not in (_utf8mb4'REJECTED',_utf8mb4'RETURNED')) or (`decision_comment` is not null)))
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Yêu cầu duyệt (vượt hạn mức / dưới giá sàn). Mỗi lần gửi duyệt là 1 dòng -> lịch sử duyệt (S4-05).';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `approval_requests` WRITE;
/*!40000 ALTER TABLE `approval_requests` DISABLE KEYS */;
