DROP TABLE IF EXISTS `ar_ledger_entries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ar_ledger_entries` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_id` bigint NOT NULL,
  `entry_type` varchar(30) NOT NULL COMMENT 'OPENING_BALANCE | INVOICE | PAYMENT | CREDIT_NOTE | ADJUSTMENT',
  `debit_amount` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT 'Phát sinh tăng nợ',
  `credit_amount` decimal(18,2) NOT NULL DEFAULT '0.00' COMMENT 'Phát sinh giảm nợ',
  `ref_type` varchar(40) DEFAULT NULL,
  `ref_id` bigint DEFAULT NULL,
  `entry_date` date NOT NULL,
  `note` text,
  `reverses_entry_id` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_ar_ledger_entries_created_by` (`created_by`),
  KEY `ix_ledger_customer` (`customer_id`,`entry_date`,`id`),
  KEY `ix_ar_ledger_entries_customer_id` (`customer_id`),
  KEY `ix_ar_ledger_entries_reverses_entry_id` (`reverses_entry_id`),
  CONSTRAINT `fk_ar_ledger_entries_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_ar_ledger_entries_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `fk_ar_ledger_entries_reverses_entry_id` FOREIGN KEY (`reverses_entry_id`) REFERENCES `ar_ledger_entries` (`id`),
  CONSTRAINT `ar_ledger_entries_chk_1` CHECK ((`entry_type` in (_utf8mb4'OPENING_BALANCE',_utf8mb4'INVOICE',_utf8mb4'PAYMENT',_utf8mb4'CREDIT_NOTE',_utf8mb4'ADJUSTMENT'))),
  CONSTRAINT `ck_ar_ledger_entries_1` CHECK (((`debit_amount` >= 0) and (`credit_amount` >= 0) and ((`debit_amount` > 0) <> (`credit_amount` > 0))))
) ENGINE=InnoDB AUTO_INCREMENT=122 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SỔ CÔNG NỢ phải thu. CHỈ INSERT; sửa sai bằng bút toán đảo (reverses_entry_id). OPENING_BALANCE dùng nhập số dư đầu kỳ từ dữ liệu cũ.';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `ar_ledger_entries` WRITE;
/*!40000 ALTER TABLE `ar_ledger_entries` DISABLE KEYS */;
