DROP TABLE IF EXISTS `delivery_notes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `delivery_notes` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `delivery_no` varchar(30) NOT NULL,
  `order_id` bigint NOT NULL,
  `warehouse_id` bigint NOT NULL,
  `pick_list_id` bigint DEFAULT NULL,
  `trip_id` bigint DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'ISSUED' COMMENT 'ISSUED | IN_TRANSIT | DELIVERED | FAILED',
  `issued_at` datetime NOT NULL,
  `issued_by` bigint DEFAULT NULL,
  `recipient_name` varchar(150) DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `failure_reason` text,
  `shortage_action` varchar(20) DEFAULT NULL COMMENT 'Xử lý phần thiếu: BACKORDER giao bổ sung sau | CLOSE đóng phần thiếu; NULL nếu xuất đủ',
  `backorder_due_at` datetime DEFAULT NULL COMMENT 'Lịch giao bổ sung (UTC)',
  `shortage_note` text COMMENT 'Ghi chú xử lý phần thiếu',
  `delivery_remark` text COMMENT 'Ghi chú lúc giao hàng / ghi chú bổ sung khi giao không thành công (S6-08)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `delivery_no` (`delivery_no`),
  UNIQUE KEY `ux_delivery_notes_pick_order` (`pick_list_id`,`order_id`),
  KEY `fk_delivery_notes_issued_by` (`issued_by`),
  KEY `fk_delivery_notes_created_by` (`created_by`),
  KEY `fk_delivery_notes_updated_by` (`updated_by`),
  KEY `ix_delivery_order` (`order_id`),
  KEY `ix_delivery_notes_order_id` (`order_id`),
  KEY `ix_delivery_notes_warehouse_id` (`warehouse_id`),
  KEY `ix_delivery_notes_pick_list_id` (`pick_list_id`),
  KEY `ix_delivery_notes_trip_id` (`trip_id`),
  CONSTRAINT `fk_delivery_notes_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_delivery_notes_issued_by` FOREIGN KEY (`issued_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_delivery_notes_order_id` FOREIGN KEY (`order_id`) REFERENCES `sales_orders` (`id`),
  CONSTRAINT `fk_delivery_notes_pick_list_id` FOREIGN KEY (`pick_list_id`) REFERENCES `pick_lists` (`id`),
  CONSTRAINT `fk_delivery_notes_trip_id` FOREIGN KEY (`trip_id`) REFERENCES `delivery_trips` (`id`),
  CONSTRAINT `fk_delivery_notes_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_delivery_notes_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`),
  CONSTRAINT `ck_delivery_notes_1` CHECK (((`shortage_action` is null) or (`shortage_action` <> _utf8mb4'BACKORDER') or (`backorder_due_at` is not null))),
  CONSTRAINT `delivery_notes_chk_1` CHECK ((`status` in (_utf8mb4'ISSUED',_utf8mb4'IN_TRANSIT',_utf8mb4'DELIVERED',_utf8mb4'FAILED'))),
  CONSTRAINT `delivery_notes_chk_2` CHECK ((`shortage_action` in (_utf8mb4'BACKORDER',_utf8mb4'CLOSE')))
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Phiếu xuất kho (1 phiếu / 1 đơn). Xác nhận rồi không sửa (S6-05). Giao xong mới đủ điều kiện xuất hoá đơn.';
/*!40101 SET character_set_client = @saved_cs_client */;

