CREATE TABLE `delivery_trips` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `trip_no` varchar(30) NOT NULL,
  `warehouse_id` bigint NOT NULL,
  `region_id` bigint DEFAULT NULL,
  `driver_name` varchar(150) DEFAULT NULL,
  `driver_phone` varchar(20) DEFAULT NULL,
  `vehicle_plate` varchar(20) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'PLANNED' COMMENT 'PLANNED | RUNNING | COMPLETED',
  `planned_departure` datetime DEFAULT NULL,
  `expected_return_at` datetime DEFAULT NULL COMMENT 'Quá giờ -> cảnh báo (S6-07)',
  `departed_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `note` text,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `trip_no` (`trip_no`),
  KEY `fk_delivery_trips_created_by` (`created_by`),
  KEY `fk_delivery_trips_updated_by` (`updated_by`),
  KEY `ix_delivery_trips_warehouse_id` (`warehouse_id`),
  KEY `ix_delivery_trips_region_id` (`region_id`),
  CONSTRAINT `fk_delivery_trips_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_delivery_trips_region_id` FOREIGN KEY (`region_id`) REFERENCES `regions` (`id`),
  CONSTRAINT `fk_delivery_trips_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_delivery_trips_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`),
  CONSTRAINT `delivery_trips_chk_1` CHECK ((`status` in (_utf8mb4'PLANNED',_utf8mb4'RUNNING',_utf8mb4'COMPLETED')))
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Chuyến giao hàng (phân tuyến). Tài xế không phải user hệ thống nên lưu thẳng tên/biển số (S6-06).';
