/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lots` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint NOT NULL,
  `lot_no` varchar(50) NOT NULL,
  `manufacture_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `supplier_id` bigint DEFAULT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `expired_issue_approved_by` bigint DEFAULT NULL COMMENT 'Quản lý kho cho phép xuất lô đã quá hạn (S6-01)',
  `expired_issue_approved_at` datetime DEFAULT NULL COMMENT 'Thời điểm cho phép (UTC)',
  `expired_issue_reason` text COMMENT 'Lý do bắt buộc khi cho phép',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
