INSERT INTO `notifications` VALUES (1,10,'RESERVATION_EXPIRED','Đơn DH261016-0002 hết hạn giữ chỗ hàng','Đơn DH261016-0002 của Đại lý Demo Đông Á đã qua ngày giao mong muốn mà chưa xuất kho, hàng không còn được giữ. Đơn vẫn ở trạng thái Đã duyệt; hệ thống giữ lại hàng khi kho tạo phiếu soạn nếu còn tồn.','ORDER',69,NULL,NULL,'2026-10-22 08:49:37',NULL),(2,10,'ORDER_DELIVERY_OVERDUE','Đơn DH261016-0002 đã quá ngày giao mong muốn','Đơn DH261016-0002 của Đại lý Demo Đông Á có ngày giao mong muốn 17/10/2026 nhưng chưa giao xong. Vui lòng liên hệ kho và đại lý để xử lý.','ORDER',69,NULL,NULL,'2026-10-22 08:49:37',NULL),(3,10,'ORDER_DELIVERY_OVERDUE','Đơn DH261017-0004 đã quá ngày giao mong muốn','Đơn DH261017-0004 của Đại lý Demo Phúc Thịnh có ngày giao mong muốn 18/10/2026 nhưng chưa giao xong. Vui lòng liên hệ kho và đại lý để xử lý.','ORDER',73,NULL,NULL,'2026-10-22 08:49:37',NULL);
