DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `receipt_no` varchar(30) NOT NULL,
  `customer_id` bigint NOT NULL,
  `amount` decimal(18,2) NOT NULL DEFAULT '0.00',
  `method` varchar(30) NOT NULL COMMENT 'CASH | BANK_TRANSFER',
  `payment_date` date NOT NULL,
  `collected_by` bigint NOT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'CONFIRMED' COMMENT 'PENDING_HANDOVER | CONFIRMED | VOIDED',
  `receipt_file_id` bigint DEFAULT NULL,
  `confirmed_by` bigint DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `void_reason` text,
  `voided_by` bigint DEFAULT NULL,
  `voided_at` datetime DEFAULT NULL,
  `note` text,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `receipt_no` (`receipt_no`),
  KEY `fk_payments_confirmed_by` (`confirmed_by`),
  KEY `fk_payments_voided_by` (`voided_by`),
  KEY `fk_payments_created_by` (`created_by`),
  KEY `fk_payments_updated_by` (`updated_by`),
  KEY `ix_payments_customer` (`customer_id`,`payment_date`),
  KEY `ix_payments_collector` (`collected_by`,`payment_date`),
  KEY `ix_payments_customer_id` (`customer_id`),
  KEY `ix_payments_receipt_file_id` (`receipt_file_id`),
  CONSTRAINT `fk_payments_collected_by` FOREIGN KEY (`collected_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_payments_confirmed_by` FOREIGN KEY (`confirmed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_payments_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_payments_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `fk_payments_receipt_file_id` FOREIGN KEY (`receipt_file_id`) REFERENCES `file_objects` (`id`),
  CONSTRAINT `fk_payments_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_payments_voided_by` FOREIGN KEY (`voided_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_payments_1` CHECK ((`amount` > 0)),
  CONSTRAINT `ck_payments_2` CHECK (((`status` <> _utf8mb4'VOIDED') or (`void_reason` is not null))),
  CONSTRAINT `payments_chk_1` CHECK ((`amount` > 0)),
  CONSTRAINT `payments_chk_2` CHECK ((`method` in (_utf8mb4'CASH',_utf8mb4'BANK_TRANSFER'))),
  CONSTRAINT `payments_chk_3` CHECK ((`status` in (_utf8mb4'PENDING_HANDOVER',_utf8mb4'CONFIRMED',_utf8mb4'VOIDED')))
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Phiếu thu. Thu tiền theo tuyến ở trạng thái PENDING_HANDOVER cho tới khi kế toán xác nhận (S7-05). Không xoá, chỉ VOIDED.';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `payments` WRITE;
/*!40000 ALTER TABLE `payments` DISABLE KEYS */;
