CREATE TABLE `permissions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `code` varchar(60) NOT NULL,
  `module` varchar(40) NOT NULL COMMENT 'Sản phẩm & bảng giá, Đơn hàng, Tồn kho, ...',
  `action` varchar(20) NOT NULL COMMENT 'VIEW | CREATE | UPDATE | APPROVE | ...',
  `description` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Danh mục quyền chi tiết (vd ORDER_APPROVE). Ánh xạ từ ma trận F/W/R trong sheet User Roles.';
