INSERT INTO `permissions` VALUES (1,'PRODUCT_VIEW','Sản phẩm & bảng giá','VIEW','Xem sản phẩm và bảng giá'),(2,'PRODUCT_MANAGE','Sản phẩm & bảng giá','MANAGE','Thêm, sửa sản phẩm và bảng giá'),(3,'COST_PRICE_VIEW','Sản phẩm & bảng giá','VIEW','Xem giá vốn và biên lợi nhuận'),(4,'CUSTOMER_VIEW','Đại lý & hạn mức công nợ','VIEW','Xem đại lý và hạn mức công nợ'),(5,'CUSTOMER_MANAGE','Đại lý & hạn mức công nợ','MANAGE','Thêm, sửa đại lý và hạn mức công nợ'),(6,'CREDIT_MANAGE','Đại lý & hạn mức công nợ','MANAGE','Sửa hạn mức công nợ, khoá và mở giao dịch đại lý'),(7,'CUSTOMER_ASSIGN','Đại lý & hạn mức công nợ','MANAGE','Phân công, chuyển giao nhân viên kinh doanh phụ trách đại lý'),(8,'ORDER_VIEW','Đơn hàng','VIEW','Xem đơn hàng'),(9,'ORDER_MANAGE','Đơn hàng','MANAGE','Tạo, sửa, huỷ đơn hàng'),(10,'ORDER_APPROVAL_VIEW','Duyệt đơn & giá đặc biệt','VIEW','Xem đơn chờ duyệt'),(11,'ORDER_APPROVE','Duyệt đơn & giá đặc biệt','APPROVE','Duyệt đơn vượt hạn mức, giá dưới giá sàn'),(12,'INVENTORY_VIEW','Tồn kho & nhập kho','VIEW','Xem tồn kho và phiếu nhập'),(13,'INVENTORY_MANAGE','Tồn kho & nhập kho','MANAGE','Nhập kho, chuyển kho, kiểm kê'),(14,'WAREHOUSE_MANAGE','Tồn kho & nhập kho','MANAGE','Thêm, sửa kho và vị trí lưu trong kho'),(15,'STOCKTAKE_FINALIZE','Tồn kho & nhập kho','APPROVE','Chốt phiếu kiểm kê, điều chỉnh tồn về số đếm'),(16,'DELIVERY_VIEW','Phiếu xuất & giao hàng','VIEW','Xem phiếu xuất và giao hàng'),(17,'DELIVERY_MANAGE','Phiếu xuất & giao hàng','MANAGE','Soạn, xuất và giao hàng'),(18,'INVOICE_VIEW','Hoá đơn & công nợ','VIEW','Xem hoá đơn và công nợ'),(19,'INVOICE_MANAGE','Hoá đơn & công nợ','MANAGE','Phát hành hoá đơn, ghi nhận thanh toán'),(20,'PAYMENT_COLLECT','Hoá đơn & công nợ','CREATE','Thu tiền theo tuyến tại cửa hàng, chờ nộp về công ty'),(21,'RETURN_VIEW','Trả hàng & điều chỉnh','VIEW','Xem phiếu trả hàng và điều chỉnh'),(22,'RETURN_MANAGE','Trả hàng & điều chỉnh','MANAGE','Lập phiếu trả hàng và điều chỉnh'),(23,'REPORT_VIEW','Báo cáo & dashboard','VIEW','Xem báo cáo và dashboard'),(24,'SALES_TARGET_MANAGE','Báo cáo & dashboard','MANAGE','Đặt và sửa chỉ tiêu doanh số theo tháng cho nhân viên và khu vực'),(25,'USER_VIEW','Người dùng & nhật ký','VIEW','Xem tài khoản người dùng và nhật ký'),(26,'USER_MANAGE','Người dùng & nhật ký','MANAGE','Tạo, sửa, khoá tài khoản người dùng'),(27,'AUDIT_LOG_VIEW','Người dùng & nhật ký','VIEW','Xem nhật ký thao tác trên tồn kho, giá, công nợ, hoá đơn');
