/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `price_lists` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `code` varchar(40) NOT NULL,
  `name` varchar(150) NOT NULL,
  `customer_group_id` bigint NOT NULL,
  `version_no` int NOT NULL DEFAULT '1',
  `previous_version_id` bigint DEFAULT NULL,
  `valid_from` date NOT NULL,
  `valid_to` date DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT | ACTIVE | EXPIRED',
  `is_locked` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'true khi đã có đơn dùng bảng giá này',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `fk_price_lists_created_by` (`created_by`),
  KEY `fk_price_lists_updated_by` (`updated_by`),
  KEY `ix_price_lists_customer_group_id` (`customer_group_id`),
  KEY `ix_price_lists_previous_version_id` (`previous_version_id`),
  CONSTRAINT `fk_price_lists_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_price_lists_customer_group_id` FOREIGN KEY (`customer_group_id`) REFERENCES `customer_groups` (`id`),
  CONSTRAINT `fk_price_lists_previous_version_id` FOREIGN KEY (`previous_version_id`) REFERENCES `price_lists` (`id`),
  CONSTRAINT `fk_price_lists_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `ck_price_lists_1` CHECK (((`valid_to` is null) or (`valid_to` >= `valid_from`))),
  CONSTRAINT `price_lists_chk_1` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'ACTIVE',_utf8mb4'EXPIRED')))
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Bảng giá theo nhóm khách + thời gian hiệu lực. Đã phát sinh đơn -> khoá, chỉ tạo phiên bản mới (S2-10).';
/*!40101 SET character_set_client = @saved_cs_client */;

