INSERT INTO `roles` VALUES (1,'CUSTOMER','Đại lý','Cửa hàng/đại lý mua sỉ, dùng cổng đặt hàng',1,'2026-10-22 14:39:35',NULL,'2026-10-22 14:39:35',NULL),(2,'SALES_REP','Nhân viên kinh doanh','Người đi thị trường, chăm sóc nhóm đại lý',1,'2026-10-22 14:39:35',NULL,'2026-10-22 14:39:35',NULL),(3,'SALES_MANAGER','Quản lý kinh doanh','Duyệt đơn ngoại lệ, xem giá vốn và biên lợi nhuận',1,'2026-10-22 14:39:35',NULL,'2026-10-22 14:39:35',NULL),(4,'WAREHOUSE','Nhân viên kho','Soạn hàng, nhập kho, kiểm kê',1,'2026-10-22 14:39:35',NULL,'2026-10-22 14:39:35',NULL),(5,'WH_MANAGER','Quản lý kho','Duyệt điều chỉnh tồn, chuyển kho, chốt kiểm kê',1,'2026-10-22 14:39:35',NULL,'2026-10-22 14:39:35',NULL),(6,'ACCOUNTANT','Kế toán công nợ','Phát hành hoá đơn, ghi nhận thanh toán',1,'2026-10-22 14:39:35',NULL,'2026-10-22 14:39:35',NULL),(7,'ADMIN','Quản trị hệ thống','Quản lý tài khoản, vai trò, nhật ký hệ thống',1,'2026-10-22 14:39:35',NULL,'2026-10-22 14:39:35',NULL);
