DROP TABLE IF EXISTS `sales_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_orders` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `order_no` varchar(30) NOT NULL,
  `customer_id` bigint NOT NULL,
  `delivery_address_id` bigint NOT NULL,
  `warehouse_id` bigint NOT NULL COMMENT 'Kho phục vụ, chốt tại thời điểm tạo đơn',
  `sales_rep_id` bigint DEFAULT NULL,
  `source` varchar(30) NOT NULL DEFAULT 'SALES_REP' COMMENT 'SALES_REP | PORTAL',
  `status` varchar(30) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT | PENDING_APPROVAL | APPROVED | PICKING | SHIPPED | DELIVERED | CLOSED | REJECTED | CANCELLED',
  `requested_delivery_date` date DEFAULT NULL,
  `subtotal_amount` decimal(18,2) NOT NULL DEFAULT '0.00',
  `discount_amount` decimal(18,2) NOT NULL DEFAULT '0.00',
  `total_amount` decimal(18,2) NOT NULL DEFAULT '0.00',
  `needs_approval` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Vượt hạn mức hoặc bán dưới giá sàn',
  `submitted_at` datetime DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `cancel_reason` text,
  `cancelled_at` datetime DEFAULT NULL,
  `cancelled_by` bigint DEFAULT NULL,
  `copied_from_order_id` bigint DEFAULT NULL,
  `note` text,
  `version` bigint NOT NULL DEFAULT '0' COMMENT 'Khoá lạc quan (optimistic lock)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_no` (`order_no`),
  KEY `fk_sales_orders_cancelled_by` (`cancelled_by`),
  KEY `fk_sales_orders_created_by` (`created_by`),
  KEY `fk_sales_orders_updated_by` (`updated_by`),
  KEY `ix_orders_customer` (`customer_id`,`created_at`),
  KEY `ix_orders_status` (`status`,`created_at`),
  KEY `ix_orders_rep_created` (`sales_rep_id`,`created_at`),
  KEY `ix_sales_orders_customer_id` (`customer_id`),
  KEY `ix_sales_orders_delivery_address_id` (`delivery_address_id`),
  KEY `ix_sales_orders_warehouse_id` (`warehouse_id`),
  KEY `ix_sales_orders_sales_rep_id` (`sales_rep_id`),
  KEY `ix_sales_orders_copied_from_order_id` (`copied_from_order_id`),
  CONSTRAINT `fk_sales_orders_cancelled_by` FOREIGN KEY (`cancelled_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_sales_orders_copied_from_order_id` FOREIGN KEY (`copied_from_order_id`) REFERENCES `sales_orders` (`id`),
  CONSTRAINT `fk_sales_orders_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_sales_orders_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `fk_sales_orders_delivery_address_id` FOREIGN KEY (`delivery_address_id`) REFERENCES `customer_delivery_addresses` (`id`),
  CONSTRAINT `fk_sales_orders_sales_rep_id` FOREIGN KEY (`sales_rep_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_sales_orders_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_sales_orders_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`),
  CONSTRAINT `ck_sales_orders_1` CHECK ((`total_amount` >= 0)),
  CONSTRAINT `ck_sales_orders_2` CHECK (((`status` <> _utf8mb4'CANCELLED') or (`cancel_reason` is not null))),
  CONSTRAINT `sales_orders_chk_1` CHECK ((`source` in (_utf8mb4'SALES_REP',_utf8mb4'PORTAL'))),
  CONSTRAINT `sales_orders_chk_2` CHECK ((`status` in (_utf8mb4'DRAFT',_utf8mb4'PENDING_APPROVAL',_utf8mb4'APPROVED',_utf8mb4'PICKING',_utf8mb4'SHIPPED',_utf8mb4'DELIVERED',_utf8mb4'CLOSED',_utf8mb4'REJECTED',_utf8mb4'CANCELLED')))
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Đơn bán hàng. Giỏ hàng của cổng đại lý = đơn ở trạng thái DRAFT (không cần bảng cart riêng).';
/*!40101 SET character_set_client = @saved_cs_client */;

