CREATE TABLE `warehouses` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `code` varchar(30) NOT NULL,
  `name` varchar(150) NOT NULL,
  `description` varchar(200) DEFAULT NULL COMMENT 'Mô tả ngắn hiện dưới tên kho, vd Kho chính, Khu cách ly hàng lỗi (S5-03)',
  `address` varchar(300) DEFAULT NULL,
  `manager_user_id` bigint DEFAULT NULL,
  `warehouse_type` varchar(30) NOT NULL DEFAULT 'SELLABLE' COMMENT 'SELLABLE | DEFECT',
  `status` varchar(30) NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE | INACTIVE',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_by` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `fk_warehouses_created_by` (`created_by`),
  KEY `fk_warehouses_updated_by` (`updated_by`),
  KEY `ix_warehouses_manager_user_id` (`manager_user_id`),
  CONSTRAINT `fk_warehouses_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_warehouses_manager_user_id` FOREIGN KEY (`manager_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_warehouses_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `warehouses_chk_1` CHECK ((`warehouse_type` in (_utf8mb4'SELLABLE',_utf8mb4'DEFECT'))),
  CONSTRAINT `warehouses_chk_2` CHECK ((`status` in (_utf8mb4'ACTIVE',_utf8mb4'INACTIVE')))
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Kho. warehouse_type = DEFECT là ''kho hàng lỗi'' nhận hàng trả bị hỏng (S8-01).';
