-- Mã đơn DHyyMMdd-NNNN lấy theo ngày tạo (giờ Việt Nam); sau khi dời ngày thì đánh lại cho khớp
DROP TEMPORARY TABLE IF EXISTS demo_order_no;
CREATE TEMPORARY TABLE demo_order_no (id BIGINT PRIMARY KEY, old_no VARCHAR(30), new_no VARCHAR(30));
INSERT INTO demo_order_no
SELECT id, order_no, CONCAT('DH', DATE_FORMAT(created_at + INTERVAL 7 HOUR, '%y%m%d'), '-',
       LPAD(ROW_NUMBER() OVER (PARTITION BY DATE(created_at + INTERVAL 7 HOUR) ORDER BY created_at, id), 4, '0'))
FROM sales_orders;
DELETE FROM demo_order_no WHERE old_no = new_no;
UPDATE sales_orders o JOIN demo_order_no m ON m.id = o.id SET o.order_no = CONCAT('#', o.id);
UPDATE sales_orders o JOIN demo_order_no m ON m.id = o.id SET o.order_no = m.new_no;
UPDATE `audit_logs` x JOIN demo_order_no m ON CAST(x.`new_values` AS CHAR) LIKE CONCAT('%', m.old_no, '%') SET x.`new_values` = REPLACE(CAST(x.`new_values` AS CHAR), m.old_no, CONCAT('{#', m.id, '#}'));
